# Discogs release number written out ("Discogs: 1441661", "DISCOGS_RELEASE_ID=1441661")
_BARE_MBID = re.compile(r"(?<![0-9a-zA-Z/=-])(" + _MBID.pattern + r")(?![0-9a-zA-Z-])", re.I)


