IMAGE_EXT = {".jpg", ".jpeg", ".png", ".gif", ".bmp", ".webp", ".tif", ".tiff"}


# --- match_albums.py:6568
# Images that are not scans of the release: covers saved from the web, rip
# screenshots and spectrum/analysis pictures ("tech.info/Au.jpg", "ksnip_...").
_NOT_A_SCAN = re.compile(r"^(cover|folder|front|albumart\w*|thumb\w*|ksnip\S*|screenshot\S*|spectr\S*|au\d*|"
                         r"expose\d*|mv|dr|dynamic\S*|\d{2,4}x\d{2,4}\S*)$", re.I)


# --- match_albums.py:6570
_NOT_A_SCAN_DIR = re.compile(r"^(tech[ ._-]?info|info|spectr\S*|analysis|screens?(hots)?)$", re.I)


# --- match_albums.py:6575
# Pictures saved from shops and databases, not scanned from your copy: Amazon product
# images ("71-Q6hBQwTL._UF1000,1000_QL80_.jpg", "._AC_SL1500_"), Discogs release images
# ("R-4847696-1388801849-4582.jpg"). Their barcode is some other pressing's (Samael -
# Ceremony Of Opposites: the 2021 MDD reissue's, in a folder ripped in 2005).
_WEB_IMAGE = re.compile(r"\._(?:[A-Z]{2}\d|[A-Z]{2}_)|^R-\d{3,}-\d{9,}(?:-\d+)?$", re.I)


# --- match_albums.py:6578
def web_image(path):
    return bool(_WEB_IMAGE.search(Path(path).stem))


# --- match_albums.py:6582
_PHYSICAL_NAME = re.compile(r"back|rear|tray|inlay|disc|disk|(?<![a-z])cd\d*(?![a-z])|obi|matrix|spine|booklet|"
                            r"inside|insert|(?<![a-z])label|sticker|case", re.I)


# --- match_albums.py:6586
def scan_evidence(album_dir):
    """Does the folder hold scans of a physical copy (a back cover, tray card,
    booklet, disc or obi)? A download comes with a cover image at most, so such
    scans mean the disc was owned. Returns {"physical": bool, "why": str}."""
    try:
        from PIL import Image
    except ImportError:
        Image = None
    for dirpath, dirs, names in os.walk(album_dir):
        dirs[:] = [d for d in dirs if not _NOT_A_SCAN_DIR.match(d)]
        for n in sorted(names):
            p = Path(dirpath) / n
            if p.suffix.lower() not in IMAGE_EXT or p.suffix.lower() == ".gif" or _NOT_A_SCAN.match(p.stem) \
                    or web_image(p):
                continue
            if _PHYSICAL_NAME.search(p.stem):
                return {"physical": True, "why": f"a scan named {p.name}"}
            if Image is not None:
                try:
                    with Image.open(p) as im:
                        w, h = im.size
                except Exception:
                    continue
                if w >= 1000 and 1.15 <= w / max(h, 1) <= 1.5:
                    return {"physical": True, "why": f"a tray-card scan ({p.name})"}
    return {"physical": False, "why": ""}


# --- match_albums.py:6614
def packaging_evidence(album_dir):
    """The packaging your scans are named after: "scan-digipak.jpg", "Digi Cover.png",
    "Digibook 01.jpg", "Jewel case back.jpg" (Cynic - Carbon-Based Anatomy: the jewel case
    and digipak pressings share barcode and number; only the scans tell them apart).
    Returns a set of mc.packaging_kind values; empty when the names say nothing. A scan
    named "Inlay" or "Tray" (a jewel case's back card and tray) is a jewel case when no
    scan names another packaging (Sadist - Spellbound)."""
    out, jewel_parts = set(), False
    for dirpath, dirs, names in os.walk(album_dir):
        dirs[:] = [d for d in dirs if not _NOT_A_SCAN_DIR.match(d)]
        for n in names:
            p = Path(dirpath) / n
            if p.suffix.lower() in IMAGE_EXT and not web_image(p):
                k = mc.packaging_kind(p.stem)
                if k:
                    out.add(k)
                elif re.search(r"(?<![a-z])(?:inlay|tray)(?![a-z])", p.stem.casefold()):
                    jewel_parts = True
    return out or ({"jewel"} if jewel_parts else set())


# --- match_albums.py:6779
# each scan's contents (md5), as list_images last read them: the per-scan cache keys
_DIGESTS = {}


# --- match_albums.py:6782
def _scan_digest(path):
    import hashlib
    d = _DIGESTS.get(str(path))
    if d is None:
        try:
            d = hashlib.md5(Path(path).read_bytes()).hexdigest()
        except OSError:
            d = "path:" + str(path)                   # not readable: a reading of nothing
        _DIGESTS[str(path)] = d
    return d


# --- match_albums.py:6820
def _cached(db, kind, key, compute):
    """OCR is slow (seconds per image); store its result so re-evaluating an
    album after a script fix does not redo it."""
    if db is None:
        return compute()
    db.execute("CREATE TABLE IF NOT EXISTS ocr_cache (key TEXT PRIMARY KEY, value TEXT)")
    row = db.execute("SELECT value FROM ocr_cache WHERE key=?", (f"{kind}:{key}",)).fetchone()
    if row:
        return json.loads(row[0])
    value = compute()
    db.execute("INSERT OR REPLACE INTO ocr_cache VALUES (?,?)", (f"{kind}:{key}", json.dumps(value)))
    db.commit()
    return value


# --- match_albums.py:6835
def ocr_workers():
    """How many tesseract runs at once: a few, leaving one processor free."""
    return max(1, min(4, (os.cpu_count() or 2) - 1))


# --- match_albums.py:6841
_TESSERACT_SLOTS = None


# --- match_albums.py:6842
_TESSERACT_GUARD = threading.Lock()


# --- match_albums.py:6845
def _tesseract(*args, **kw):
    """subprocess.run of tesseract, no more at a time in the process than ocr_workers() (albums
    looked up at once each read their scans: their pools must not add up)."""
    import subprocess
    global _TESSERACT_SLOTS
    with _TESSERACT_GUARD:
        if _TESSERACT_SLOTS is None:
            _TESSERACT_SLOTS = threading.BoundedSemaphore(max(1, ocr_workers()))
    with _TESSERACT_SLOTS, stagetimes.stage("ocr"):
        return subprocess.run(*args, **kw)


# --- match_albums.py:6876
def _tess_env():
    """tesseract's environment: one thread each (several run at once, see _pmap), unless
    you set OMP_THREAD_LIMIT yourself."""
    env = dict(os.environ)
    env.setdefault("OMP_THREAD_LIMIT", "1")
    return env


# --- match_albums.py:7317
_LANGS = None


# --- match_albums.py:7320
def ocr_langs():
    """English, plus Russian and Japanese when their tesseract packs are installed
    (tesseract-ocr-rus, tesseract-ocr-jpn): FONO sleeves, Japanese obi strips."""
    global _LANGS
    if _LANGS is None:
        import subprocess
        try:
            have = subprocess.run(["tesseract", "--list-langs"], capture_output=True, text=True,
                                  timeout=30).stdout.split()
        except Exception:
            have = []
        _LANGS = "+".join(x for x in ("eng", "rus", "jpn") if x in have) or "eng"
    return _LANGS


# --- match_albums.py:7337
# OCR-3: each scan is read in its own script. The language packs of scripts other than the
# Latin alphabet, by the script tesseract's OSD names; every other pack is a Latin one.
_SCRIPT_PACKS = {"Cyrillic": {"rus", "ukr", "bul", "srp", "mkd", "bel"},
                 "Japanese": {"jpn", "jpn_vert"}, "Hiragana": {"jpn", "jpn_vert"},
                 "Katakana": {"jpn", "jpn_vert"},
                 "Han": {"chi_sim", "chi_tra", "chi_sim_vert", "chi_tra_vert", "jpn", "jpn_vert"},
                 "Hangul": {"kor", "kor_vert"}, "Greek": {"ell", "grc"}, "Arabic": {"ara", "fas", "urd"},
                 "Hebrew": {"heb", "yid"}}


# --- match_albums.py:7343
_NON_LATIN = set().union(*_SCRIPT_PACKS.values())


# --- match_albums.py:7344
OSD_MIN_CONFIDENCE = 1.0      # under it OSD's script is a guess (a German label read as "Japanese, 0.25")


# --- match_albums.py:7354
def _latin_langs(langs):
    """The Latin-alphabet packs of a language set ("eng+deu" of "eng+deu+rus+jpn"), English
    at least."""
    return "+".join([x for x in langs.split("+") if x not in _NON_LATIN] or ["eng"])


# --- match_albums.py:7360
def _open_reduced(path, box):
    """A scan in colour (RGB), at most BOX pixels, reduced BEFORE it is converted (a JPEG
    decoded at a fraction of its size, the rest shrunk first), so a 6000 x 6000 scan is never
    held in colour at full size. Returns (image, its original size, its dpi or None)."""
    from PIL import Image
    with Image.open(path) as src:
        size, dpi = src.size, src.info.get("dpi")
        try:
            src.draft("RGB", box)                     # (JPEG: decoded reduced; others: no-op)
        except Exception:
            pass
        im = src
        if im.mode not in ("1", "P"):                 # (palette images are shrunk in colour)
            try:
                im = im.copy()
                im.thumbnail(box)
            except Exception:
                im = src
        im = im.convert("RGB")
    im.thumbnail(box)
    return im, size, dpi


# --- match_albums.py:7383
def _page_image(path):
    """A scan as tesseract reads it best: in colour (tesseract picks the channel the print
    stands out in; a greyscale copy loses blue-on-black print: Popol Vuh's label) at most
    2400 pixels, with its resolution carried over. Returns (image, save options)."""
    im, (w, _h), dpi = _open_reduced(path, (2400, 2400))
    opts = {}
    try:
        if dpi and float(dpi[0]) >= 50:
            opts["dpi"] = (round(float(dpi[0]) * im.size[0] / max(w, 1)),) * 2
    except (TypeError, ValueError, IndexError):
        pass
    return im, opts


# --- match_albums.py:7397
def scan_script(png):
    """The script tesseract's OSD finds on an image file ("Latin", "Cyrillic", "Japanese"...),
    or "" when it finds none (too little text) or is unsure (OSD_MIN_CONFIDENCE)."""
    try:
        r = _tesseract(["tesseract", str(png), "stdout", "--psm", "0"], capture_output=True, text=True,
                       timeout=30, env=_tess_env())
    except Exception:
        return ""
    m = re.search(r"^Script: (\w+)\s*$", r.stdout or "", re.M)
    c = re.search(r"^Script confidence: ([\d.]+)", r.stdout or "", re.M)
    if not m or not c or float(c.group(1)) < OSD_MIN_CONFIDENCE:
        return ""
    return m.group(1)


# --- match_albums.py:7412
def _osd_script(im, opts, png=None):
    """scan_script of a page image (_page_image's), on a copy at most 1600 pixels: OSD on a
    whole 2400-pixel back cover took over a second, on that copy about half."""
    import tempfile
    if png is not None and max(im.size) <= 1600:
        return scan_script(png)
    small = im.copy()
    small.thumbnail((1600, 1600))
    o = dict(opts)
    if "dpi" in o:
        o["dpi"] = (max(50, round(o["dpi"][0] * small.size[0] / max(im.size[0], 1))),) * 2
    with tempfile.NamedTemporaryFile(suffix=".png") as tmp:
        small.save(tmp.name, **o)
        return scan_script(tmp.name)


# --- match_albums.py:7428
def _tess_page(png, langs, timeout=120):
    """tesseract's sparse-text reading of an image file in LANGS: (text, words), words being
    (confidence, word) of each word read."""
    import tempfile
    with tempfile.TemporaryDirectory() as d:
        out = os.path.join(d, "page")
        _tesseract(["tesseract", str(png), out, "--psm", "11", "-l", langs, "txt", "tsv"],
                   capture_output=True, text=True, timeout=timeout, env=_tess_env())
        try:
            text = Path(out + ".txt").read_text(encoding="utf-8", errors="replace")
        except OSError:
            text = ""
        words = []
        try:
            for row in Path(out + ".tsv").read_text(encoding="utf-8", errors="replace").splitlines()[1:]:
                f = row.split("\t")
                if len(f) >= 12 and f[0] == "5" and f[11].strip():
                    try:
                        words.append((float(f[10]), f[11].strip()))
                    except ValueError:
                        continue
        except OSError:
            pass
    return text, words


# --- match_albums.py:7454
_LATIN_WORD = re.compile(r"[A-Za-z][a-z]{2,}|[A-Z]{3,}")


# --- match_albums.py:7457
def _latin_poor(words):
    """Too little read in the Latin alphabet to trust: fewer than three sure (confidence 70)
    words of three letters or codes."""
    good = [w for c, w in words if c >= 70 and (_LATIN_WORD.fullmatch(w.strip(".,:;()'\"")) or
                                                _CODE_LIKE.fullmatch(w.strip(".,:;()")))]
    return len(good) < 3


# --- match_albums.py:7465
def _sure_chars(words):
    """How much a reading read for sure: the letters and digits of its words of confidence 70
    (not the long-vowel marks and dots noise reads as "ーー")."""
    return sum(n for c, w in words if c >= 70
               for n in [sum(ch.isalnum() and ch not in "ー〜・" for ch in w)] if n)


# --- match_albums.py:7475
# OCR-3: one decision per scan and language set, shared by its page text and its spines:
# (scan digest, language set) -> (the packs chosen, the page text). The first to ask reads the
# page (one OSD a scan); the other waits for it and takes its reading. The newest 256 kept.
_SCAN_PAGES = {}


# --- match_albums.py:7476
_SCAN_PAGE_LOCKS = {}


# --- match_albums.py:7477
_SCAN_PAGES_GUARD = threading.Lock()


# --- match_albums.py:7478
_SCAN_PAGES_MAX = 256


# --- match_albums.py:7481
def _read_page(path):
    """scan_page's reading, not shared: (packs chosen, text)."""
    import tempfile
    langs = ocr_langs()
    latin = _latin_langs(langs)
    im, opts = _page_image(path)
    with tempfile.NamedTemporaryFile(suffix=".png") as tmp:
        im.save(tmp.name, **opts)
        if latin == langs:
            return latin, _tess_page(tmp.name, latin)[0]
        script = _osd_script(im, opts, tmp.name)
        own = [x for x in langs.split("+") if x in _SCRIPT_PACKS.get(script, ())]
        if script == "Latin":
            return latin, _tess_page(tmp.name, latin)[0]
        if own:
            chosen = "+".join(own + ["eng"])
            return chosen, _tess_page(tmp.name, chosen)[0]
        text, words = _tess_page(tmp.name, latin)
        if _latin_poor(words):
            text_all, words_all = _tess_page(tmp.name, langs)
            if _sure_chars(words_all) >= max(6, 1.5 * _sure_chars(words) + 1):
                # the Latin reading is kept with it: what it read is never lost
                return langs, text_all + "\n" + text
        return latin, text


# --- match_albums.py:7507
def scan_page(path):
    """OCR-3: one scan's page text, read in its own script. Returns (langs, text). With only
    Latin packs set, it is read in those. Otherwise OSD names the script: Latin is read in
    the Latin packs alone, another script in its packs and English; with no sure script, in
    the Latin packs first and, only when that reads too little, in every pack too, which is
    kept (with the Latin reading) when it reads clearly more for sure. A Latin cover is never
    read only through every pack at once. Read once a scan: its spines (scan_langs) take the
    packs chosen here."""
    key = (_scan_digest(path), ocr_langs())
    with _SCAN_PAGES_GUARD:
        lock = _SCAN_PAGE_LOCKS.setdefault(key, threading.Lock())
    with lock:
        with _SCAN_PAGES_GUARD:
            got = _SCAN_PAGES.get(key)
        if got is None:
            got = _read_page(path)
            with _SCAN_PAGES_GUARD:
                _SCAN_PAGES[key] = got
                while len(_SCAN_PAGES) > _SCAN_PAGES_MAX:
                    old = next(iter(_SCAN_PAGES))
                    _SCAN_PAGES.pop(old)
                    _SCAN_PAGE_LOCKS.pop(old, None)
    return got


# --- match_albums.py:7532
def scan_langs(path):
    """The packs a scan's spines are read in: those its page text was read in (scan_page,
    which reads the page now when nobody has yet). Only Latin packs set: those, unread."""
    langs = ocr_langs()
    latin = _latin_langs(langs)
    if latin == langs:
        return latin
    try:
        return scan_page(path)[0]
    except Exception:
        return latin


# --- match_albums.py:7545
def ocr_spines(paths):
    """Text printed along the spines of a CD tray card (catalogue numbers often
    appear only there), which page OCR misses: it runs sideways. Each side strip
    of a landscape scan is cut off, turned upright, enlarged and read."""
    import subprocess
    import tempfile
    try:
        from PIL import Image
    except ImportError:
        return ""
    chunks = []
    for p in paths:
        try:
            with Image.open(p) as src:
                w, h = src.size
        except Exception:
            continue
        spread = w / max(h, 1) >= 1.8 and w >= 1200
        if not spread and (not (1.15 <= w / max(h, 1) <= 1.6) or w < 600):
            continue                                   # tray cards are about 151 x 118 mm
        try:
            # in colour, as the page, and in the packs its page was read in (OCR-3); never
            # larger than read (a spread at 3600, a tray card's strips at 3000 tall at most)
            im = _open_reduced(p, (3600, 3600) if spread else (int(4000 * w / max(h, 1)), 4000))[0]
            langs = scan_langs(p)
        except Exception:
            continue
        w, h = im.size
        if spread:
            # a digipak or booklet spread scanned open: its spine runs down the middle
            # (Cryptopsy - Tome II: "HHR 2018-23" only there). Read the whole spread sideways.
            whole = im.copy()
            whole.thumbnail((3600, 3600))
            for angle in (90, 270):
                try:
                    with tempfile.NamedTemporaryFile(suffix=".png") as tmp:
                        whole.rotate(angle, expand=True).save(tmp.name)
                        r = _tesseract(["tesseract", tmp.name, "stdout", "--psm", "11", "-l", langs],
                                           capture_output=True, text=True, timeout=120, env=_tess_env())
                    chunks.append(r.stdout)
                except Exception:
                    continue
            continue
        strip_w = max(int(w * 0.07), 30)
        for box in ((0, 0, strip_w, h), (w - strip_w, 0, w, h)):
            strip = im.crop(box)
            scale = max(1.0, min(3.0, 3000 / h))
            if scale > 1.0:
                strip = strip.resize((int(strip.size[0] * scale), int(strip.size[1] * scale)))
            for angle in (90, 270):
                try:
                    with tempfile.NamedTemporaryFile(suffix=".png") as tmp:
                        strip.rotate(angle, expand=True).save(tmp.name)
                        r = _tesseract(["tesseract", tmp.name, "stdout", "--psm", "11", "-l", langs],
                                           capture_output=True, text=True, timeout=60, env=_tess_env())
                    chunks.append(r.stdout)
                except Exception:
                    continue
    return "\n".join(chunks)


# --- match_albums.py:7606
def barcode_regions(im, max_regions=3):
    """Where barcodes are on a scan: patches of dense vertical bars (strong horizontal
    contrast, weak vertical contrast), found on a small copy. Returns boxes in the
    image's own pixels, largest first. Needs numpy; without it, none."""
    try:
        import numpy as np
        from PIL import ImageFilter
    except ImportError:
        return []
    from collections import deque
    g = im.convert("L")
    W, H = g.size
    s = 1200 / max(W, H, 1)
    a = np.asarray(g.resize((max(1, int(W * s)), max(1, int(H * s)))), dtype=np.float32)
    if a.shape[0] < 3 or a.shape[1] < 3:
        return []
    gx = np.abs(np.diff(a, axis=1))[:-1, :]
    gy = np.abs(np.diff(a, axis=0))[:, :-1]
    energy = Image_from(np.uint8(np.clip(np.clip(gx - gy, 0, None) * 2, 0, 255))).filter(ImageFilter.BoxBlur(6))
    m = np.asarray(energy) > 60
    h, w = m.shape
    seen = np.zeros_like(m, bool)
    found = []
    for y in range(0, h, 2):
        for x in range(0, w, 2):
            if not m[y, x] or seen[y, x]:
                continue
            q, ys, xs = deque([(y, x)]), [], []
            seen[y, x] = True
            while q:
                cy, cx = q.popleft()
                ys.append(cy)
                xs.append(cx)
                for ny, nx in ((cy + 1, cx), (cy - 1, cx), (cy, cx + 1), (cy, cx - 1)):
                    if 0 <= ny < h and 0 <= nx < w and m[ny, nx] and not seen[ny, nx]:
                        seen[ny, nx] = True
                        q.append((ny, nx))
            x0, x1, y0, y1 = min(xs), max(xs), min(ys), max(ys)
            bw, bh = x1 - x0, y1 - y0
            if len(ys) > 150 and bw > 20 and bh > 8 and len(ys) > 0.5 * bw * bh:
                found.append((len(ys), (x0 / s, y0 / s, x1 / s, y1 / s)))
    found = _merge_bar_rows(found)
    found.sort(reverse=True)
    return [b for _n, b in found[:max_regions]]


# --- match_albums.py:7652
def _merge_bar_rows(found):
    """Patches side by side on one row joined into one: wide black bars have no edges
    inside, so a big barcode is found as two or three pieces (Lamb of God - Omens, Alcest's
    obi). `found` holds (pixels, box) pairs; the joined patch sums the pixels."""
    found = list(found)
    joined = True
    while joined:
        joined = False
        for i in range(len(found)):
            for j in range(i + 1, len(found)):
                (na, a), (nb, b) = found[i], found[j]
                overlap = min(a[3], b[3]) - max(a[1], b[1])
                gap = max(a[0], b[0]) - min(a[2], b[2])
                if overlap >= 0.5 * min(a[3] - a[1], b[3] - b[1]) and gap <= 0.6 * max(a[3] - a[1], b[3] - b[1]):
                    found[i] = (na + nb, (min(a[0], b[0]), min(a[1], b[1]), max(a[2], b[2]), max(a[3], b[3])))
                    del found[j]
                    joined = True
                    break
            if joined:
                break
    return found


# --- match_albums.py:7675
def barcode_patches(im, max_regions=3):
    """The barcodes on a scan, each with its bars standing upright: (grey image, box,
    turned) triples. A barcode printed sideways, along a tray card's edge (BTBAM - The Great
    Misdirect), is found on the scan turned a quarter."""
    from PIL import Image
    g = im.convert("L")
    out = [(g, b, False) for b in barcode_regions(g, max_regions)]
    turned = g.transpose(Image.ROTATE_90)
    out += [(turned, b, True) for b in barcode_regions(turned, max_regions)]
    return out


# --- match_albums.py:7788
def Image_from(arr):
    from PIL import Image
    return Image.fromarray(arr)


# --- match_albums.py:7793
def _digit_band_reads(g, box):
    """tesseract's readings of the digits under one upright barcode: the patch with its
    surroundings enlarged, and tight bands at the foot of the bars, read as a line and
    as digits only."""
    x0, y0, x1, y1 = box
    bw, bh = x1 - x0, y1 - y0
    crop = g.crop((int(max(0, x0 - bw * 0.15)), int(max(0, y0 - bh * 0.4)),
                   int(min(g.width, x1 + bw * 0.15)), int(min(g.height, y1 + bh * 0.6))))
    crops = [(crop.resize((crop.width * 2, crop.height * 2)), 6, "")]
    # the digits alone: a tight band at the foot of the bars, at the scan's own
    # resolution (Exhorder's Dissonance digipak: enlarged, or with the bars in
    # view, tesseract reads noise; the band alone reads "5 013929 020160")
    for f0, f1 in ((-0.1, 0.3), (-0.05, 0.35), (0.0, 0.3)):
        band = (int(max(0, x0 - bw * 0.15)), int(max(0, y1 + bh * f0)),
                int(min(g.width, x1 + bw * 0.1)), int(min(g.height, y1 + bh * f1)))
        if band[3] - band[1] > 8:
            crops.append((g.crop(band), 7, ""))
            crops.append((g.crop(band), 7, "0123456789"))   # no letters for a smudged digit
    out = []
    for c, psm, only in crops:
        try:
            out.append(_tess(c, psm, only=only))
        except Exception:
            continue
    return out


# --- match_albums.py:7820
def ocr_barcode_digits(paths, max_images=15, budget_s=120.0):
    """The digits printed under a barcode, read from the barcode's own patch at full
    resolution (page OCR on a reduced scan misses them: Cryptopsy - Tome II's
    8715392182327). For when no barcode decoder (pyzbar) is installed, or it read none.
    A sideways barcode is read turned upright both ways (its digits may run up or down)."""
    try:
        from PIL import Image
    except ImportError:
        return ""
    chunks, started = [], time.time()
    for p in list(paths)[:max_images]:
        if time.time() - started > budget_s:
            break
        try:
            im = Image.open(p)
            im.load()
        except Exception:
            continue
        for g, box, turned in barcode_patches(im):
            frames = [(g, box)]
            if turned:
                x0, y0, x1, y1 = box
                frames.append((g.transpose(Image.ROTATE_180), (g.width - x1, g.height - y1, g.width - x0, g.height - y0)))
            for frame, fbox in frames:
                # checked before each read too: one scan holds up to six patches, 7 reads each
                if time.time() - started > budget_s:
                    break
                chunks += _digit_band_reads(frame, fbox)
    # the first digit sits apart and is often misread: complete 6+6 digit groups by
    # the check digit - groups read on ONE line only (OCR-5): two crops each reading the left
    # group "006759" once joined into an invented "2006759006759"
    text = "\n".join(chunks)
    for m in re.finditer(r"(?<!\d)(\d{6})[^\d\n]{0,3}(\d{6})(?!\d)", text):
        code = mc.complete_ean(m.group(1) + m.group(2))
        if code:
            chunks.append(mc.COMPLETED + code)
    return "\n".join(chunks)


