def ocr_text(paths):
    """OCR via the tesseract program itself (no pytesseract needed): each scan's page text."""
    try:
        import PIL.Image  # noqa: F401
    except ImportError:
        return ""
    chunks = []
    for p in paths:
        try:
            chunks.append(scan_page(p)[1])            # in colour, in its own script (OCR-3)
        except Exception:
            continue
    return "\n".join(chunks)


