def _distinctive(code):
    """A catalogue number OCR cannot make up from a year or a phone number: 5+ characters,
    letters and digits ("omm0132")."""
    k = mc.norm_code(code)
    return len(k) >= 5 and bool(re.search(r"[a-z]", k)) and bool(re.search(r"\d", k))


