DISC_DIR = re.compile(r"^(?:cd|disc|disk|dvd|side)\s*[-_.]?\s*(?:\d+|one|two|three|four|five|six|seven|eight|"
                      r"nine|ten|[a-h])\b|^\d{1,2}$", re.I)


